// Plain JS (no build step needed) — copies the generated index/ directory
// into public/index/ so Astro serves it as static assets that the
// client-side search widget can fetch. Runs after `npm run index`, before
// `astro build`. public/index/ is git-ignored: it's fully regenerated by CI.
import { cp, rm } from "node:fs/promises";
import path from "node:path";

const root = process.cwd();
const src = path.join(root, "index");
const dest = path.join(root, "public", "index");

await rm(dest, { recursive: true, force: true });
await cp(src, dest, { recursive: true });
console.log(`Copied ${src} -> ${dest}`);
